\title[$\gamma$-Positivity of Symmetric Edge Polytopes for Few-Path Graphs]
{$\gamma$-Positivity of Symmetric Edge Polytopes for Series--Parallel Graphs
with at Most Four Paths}

\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
For two distinguished vertices $s$ and $t$, joining them with $m$ internally
disjoint paths of lengths $a_1,\dots,a_m$ yields a series--parallel graph $G(a)$,
the \emph{generalized theta graph}. The Ehrhart $h^*$-polynomial of its symmetric
edge polytope $Q_{G(a)}$ is always palindromic; a central open question asks
precisely when it is \textbf{$\gamma$-positive}, a strengthening of palindromicity
and unimodality. It is known that $\gamma$-positivity can fail once $m\ge 5$, and it
is conjectured to hold for every choice of path lengths when $m\le 4$, which would
furnish a complete classification for this family. We develop the algebraic backbone
of that classification. Working in the $\gamma$-basis $t^i(1+t)^{n-2i}$, we establish:
(i) an evaluation-positivity principle---every $\gamma$-positive polynomial is
nonnegative on $[0,\infty)$; (ii) the full cone structure of $\gamma$-positive
polynomials---closure under nonnegative scaling, addition, and multiplication across
orders, the last driven by an exact multiplication rule for $\gamma$-basis elements;
(iii) a sharp infinite family of non-examples---the \emph{flat palindrome}
$1+t+\cdots+t^n$ is $\gamma$-positive if and only if $n\le 1$, localizing the
obstruction to the two lowest coefficients; and (iv) a series--parallel product model
whose $h^*$-polynomial is $\gamma$-positive for any number of paths, exhibiting the
multiplicative regime that contains the conjectural $m\le 4$ case. Together these
results identify both the mechanism of failure (a forced negative second
$\gamma$-coefficient) and the mechanism of success (multiplicative factorization),
and reduce the classification to controlling a finite low-order window across the
parallel-join operation.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Symmetric integer sequences pervade combinatorics, discrete geometry, and algebraic
combinatorics. Given a palindromic sequence one wants to know whether its symmetry is
\emph{structural}---assembled from elementary symmetric building blocks with
nonnegative weights---or merely coincidental. The precise notion capturing structural
symmetry is \textbf{$\gamma$-positivity}, which sits strictly between palindromicity
and the weaker property of unimodality:
\[
\text{$\gamma$-positive} \;\Longrightarrow\; \text{unimodal and palindromic}.
\]

A rich source of palindromic sequences is Ehrhart theory. For a lattice polytope $P$,
the number of lattice points in the $r$-th dilate is a polynomial in $r$; its
generating function has numerator the \textbf{$h^*$-polynomial}, whose coefficients
form the $h^*$-vector. When $P$ is Gorenstein, the $h^*$-polynomial is palindromic. A
much-studied class of Gorenstein polytopes are the \textbf{symmetric edge polytopes}
$Q_G$ of finite graphs $G$: their $h^*$-polynomials are always palindromic, and
determining when they are $\gamma$-positive is an active line of inquiry.

\subsection{The family of interest}
We focus on the \textbf{generalized theta graphs}. Fix two distinguished vertices $s$
and $t$ and connect them with $m$ internally disjoint paths, the $k$-th of length
$a_k\ge 1$. The resulting graph $G(a)$ with $a=(a_1,\dots,a_m)$ is series--parallel.
The structural picture is a sharp threshold: for $m\ge 5$ there exist $a$ for which
the $h^*$-polynomial of $Q_{G(a)}$ is palindromic and unimodal but \emph{not}
$\gamma$-positive; for $m\le 4$ it is conjectured $\gamma$-positive for \emph{every}
$a$.

\subsection{Contributions}
We contribute the algebraic infrastructure on which the classification rests, together
with a sharp diagnosis of the failure mechanism: evaluation positivity
(Theorem~\ref{thm:eval}), the cone structure (Theorems~\ref{thm:smul},
\ref{thm:add}, \ref{thm:mul}), the flat-palindrome classification
(Theorem~\ref{thm:flat}), and the series--parallel product model
(Theorem~\ref{thm:model}).

\section{Preliminaries}
We work over $\R[t]$. For a polynomial $p$, $[t^k]\,p$ denotes the coefficient of
$t^k$, and $\binom{N}{j}=0$ for $j>N$. Here $n$ denotes the \emph{order} with respect
to which symmetry and $\gamma$-expansions are taken; natural-number subtraction
$n-2i$ is truncated at $0$.

\section{The $\gamma$-basis and the $\gamma$-positive cone}

\begin{definition}[$\gamma$-basis]
For $n,i\in\Z_{\ge0}$, the $i$-th $\gamma$-basis element of order $n$ is
$\Bni(t)=(1+t)^{\,n-2i}\,t^{\,i}$. For $0\le i\le\lfloor n/2\rfloor$ these form a
basis of the palindromic polynomials of order $n$.
\end{definition}

\begin{proposition}[Coefficients]\label{prop:coeff}
For all $n,i,k$,
\[
[t^k]\,\Bni=\begin{cases}\binom{n-2i}{k-i}, & i\le k,\\ 0,& i>k.\end{cases}
\]
\end{proposition}
\begin{proof}
Multiplication by $t^i$ shifts coefficients by $i$, so $[t^k]\Bni=[t^{k-i}](1+t)^{n-2i}$
for $k\ge i$ and $0$ otherwise; the binomial theorem gives $\binom{n-2i}{k-i}$.
\end{proof}

\begin{proposition}[Nonnegativity of coefficients]\label{prop:coeffnn}
Every coefficient of every $\gamma$-basis element is nonnegative.
\end{proposition}
\begin{proof}
Immediate from Proposition~\ref{prop:coeff}: binomial coefficients are nonnegative and
the alternative branch is $0$.
\end{proof}

\begin{definition}[$\gamma$-positivity]
A polynomial $p$ is \emph{$\gamma$-positive of order $n$} if there exist reals
$\gamma_0,\gamma_1,\dots\ge0$ with
$p=\sum_{i=0}^{\lfloor n/2\rfloor}\gamma_i\,\Bni=\sum_i\gamma_i(1+t)^{n-2i}t^i$.
The sequence $(\gamma_i)$ is the $\gamma$-vector.
\end{definition}

\begin{definition}[Palindromicity]
A polynomial $p$ is \emph{palindromic of order $n$} if $p_k=p_{n-k}$ for all
$0\le k\le n$.
\end{definition}

Since each $\Bni$ is palindromic, every $\gamma$-positive polynomial of order $n$ is
palindromic of order $n$; the converse fails sharply (Section~\ref{sec:flat}).

\section{Evaluation positivity}

\begin{lemma}[Basis evaluation]\label{lem:baseval}
For every $n,i$ and every $t\ge0$, $\Bni(t)\ge0$.
\end{lemma}
\begin{proof}
$\Bni(t)=(1+t)^{n-2i}t^i$ is a product of nonnegative factors when $t\ge0$, since
$1+t\ge1>0$ and $t\ge0$, and nonnegative bases raised to natural powers stay nonnegative.
\end{proof}

\begin{theorem}[Evaluation positivity]\label{thm:eval}
If $p$ is $\gamma$-positive of order $n$, then $p(t)\ge0$ for all $t\ge0$. Hence every
real root of $p$ lies in $(-\infty,0]$.
\end{theorem}
\begin{proof}
Write $p=\sum_i\gamma_i\Bni$ with $\gamma_i\ge0$. For $t\ge0$,
$p(t)=\sum_i\gamma_i\Bni(t)$ is a sum of products of nonnegatives by
Lemma~\ref{lem:baseval}, hence $\ge0$.
\end{proof}

\section{The cone structure}

\begin{theorem}[Closure under nonnegative scaling]\label{thm:smul}
If $p$ is $\gamma$-positive of order $n$ and $c\ge0$, then $c\,p$ is $\gamma$-positive
of order $n$.
\end{theorem}
\begin{proof}
If $p=\sum_i\gamma_i\Bni$ then $c\,p=\sum_i(c\gamma_i)\Bni$ with $c\gamma_i\ge0$.
\end{proof}

\begin{theorem}[Closure under addition]\label{thm:add}
If $p,q$ are $\gamma$-positive of the same order $n$, then $p+q$ is $\gamma$-positive
of order $n$.
\end{theorem}
\begin{proof}
Add the $\gamma$-vectors coefficientwise; nonnegativity is preserved.
\end{proof}

\begin{theorem}[Multiplication rule for the $\gamma$-basis]\label{thm:basismul}
If $2i\le m$ and $2j\le n$, then $B_{m,i}\cdot B_{n,j}=B_{m+n,\,i+j}$.
\end{theorem}
\begin{proof}
$B_{m,i}B_{n,j}=(1+t)^{m-2i}t^i(1+t)^{n-2j}t^j=(1+t)^{(m-2i)+(n-2j)}t^{i+j}$, and under
$2i\le m$, $2j\le n$ the exponent equals $(m+n)-2(i+j)$.
\end{proof}

\begin{theorem}[Closure under multiplication across orders]\label{thm:mul}
If $p$ is $\gamma$-positive of order $m$ and $q$ of order $n$, then $pq$ is
$\gamma$-positive of order $m+n$.
\end{theorem}
\begin{proof}
With $p=\sum_i a_i B_{m,i}$, $q=\sum_j b_j B_{n,j}$, $a_i,b_j\ge0$,
Theorem~\ref{thm:basismul} gives
$pq=\sum_{i,j}a_ib_j B_{m+n,i+j}$. Grouping by $\ell=i+j$ yields
$\gamma_\ell(pq)=\sum_{i+j=\ell}a_ib_j\ge0$, a genuine $\gamma$-expansion of order
$m+n$.
\end{proof}

\begin{corollary}[Trivial block]\label{cor:trivial}
$(1+t)^n$ is $\gamma$-positive of order $n$, with $\gamma$-vector $(1,0,\dots)$; indeed
$(1+t)^n=B_{n,0}$.
\end{corollary}

\section{The flat-palindrome family}\label{sec:flat}

\begin{definition}[Flat palindrome]
The \emph{flat palindrome of degree $n$} is $F_n(t)=1+t+\cdots+t^n=\sum_{i=0}^n t^i$.
\end{definition}

\begin{proposition}\label{prop:flatcoeff}
$[t^k]F_n=1$ for $0\le k\le n$ and $0$ otherwise; $F_n$ is palindromic and unimodal.
\end{proposition}

\begin{proposition}\label{prop:flatlow}
For $n\le1$, $F_n=(1+t)^n$, hence $F_n$ is $\gamma$-positive of order $n$.
\end{proposition}
\begin{proof}
$F_0=1=(1+t)^0$ and $F_1=1+t=(1+t)^1$; apply Corollary~\ref{cor:trivial}.
\end{proof}

\begin{theorem}[Flat-palindrome classification]\label{thm:flat}
For every $n$, $F_n$ is $\gamma$-positive of order $n$ if and only if $n\le1$.
\end{theorem}
\begin{proof}
($\Leftarrow$) is Proposition~\ref{prop:flatlow}. For ($\Rightarrow$), suppose $n\ge2$
and $F_n=\sum_i\gamma_i\Bni$ with $\gamma_i\ge0$. By Proposition~\ref{prop:coeff}, only
$i=0$ contributes to $[t^0]$, where $[t^0]B_{n,0}=\binom{n}{0}=1$, so $\gamma_0=[t^0]F_n=1$.
Only $i\in\{0,1\}$ contribute to $[t^1]$: $[t^1]B_{n,0}=\binom{n}{1}=n$ and
$[t^1]B_{n,1}=\binom{n-2}{0}=1$, so $[t^1]F_n=n\gamma_0+\gamma_1$. Since $[t^1]F_n=1$ and
$\gamma_0=1$, we get $\gamma_1=1-n\le-1<0$, contradicting $\gamma_1\ge0$.
\end{proof}

\begin{remark}
The obstruction is local to the two lowest coefficients: $\gamma_0=p_0$ and
$\gamma_1=p_1-n\,p_0$ are forced. Failure is genuine---$F_n$ is palindromic and
unimodal for all $n$, yet fails $\gamma$-positivity for $n\ge2$. This is an infinite
family of sharp non-examples and is the profile realized by the $m\ge5$
series--parallel failures.
\end{remark}

\section{A series--parallel product model}

\begin{definition}[Building block and product model]
The building block of a path of length $a$ is $P_a(t)=(1+t)^a$. For a list
$a=(a_1,\dots,a_m)$, the series (product) model is
$M_a(t)=\prod_{k=1}^m P_{a_k}(t)=(1+t)^{a_1+\cdots+a_m}$.
\end{definition}

\begin{theorem}[Product model is $\gamma$-positive]\label{thm:model}
For every list $a=(a_1,\dots,a_m)$, $M_a$ is $\gamma$-positive of order
$a_1+\cdots+a_m$. In particular $\gamma$-positivity holds throughout the model for
every $m$, a fortiori for $m\le4$.
\end{theorem}
\begin{proof}
Induct on the list. The empty product is $1=(1+t)^0$, $\gamma$-positive by
Corollary~\ref{cor:trivial}. For the step, $M_{(a_0,a')}=(1+t)^{a_0}\,M_{a'}$; the first
factor is $\gamma$-positive of order $a_0$, the second of order $\sum a'$ by induction,
and Theorem~\ref{thm:mul} gives $\gamma$-positivity of order $a_0+\sum a'$.
\end{proof}

\begin{example}
Two-path join ($m=2$), $a=(2,3)$: $M_a=(1+t)^5$ is $\gamma$-positive of order $5$.
Four-path join ($m=4$), $a=(1,2,2,3)$: $M_a=(1+t)^8$ is $\gamma$-positive of order $8$.
\end{example}

\section{Discussion}
The product model is the \emph{success} pole (factorization into $\gamma$-positive
blocks), and the flat palindrome is the \emph{failure} pole (a minimal, universal
obstruction). The classification asks where the boundary falls, and the algebra
localizes it to a finite low-order window: $\gamma_0=p_0$, $\gamma_1=p_1-n\,p_0$, so any
palindromic $h^*$-polynomial with $p_1<n\,p_0$ is not $\gamma$-positive regardless of
higher structure. This separates $\gamma$-positivity strictly from unimodality and from
nonnegativity on $[0,\infty)$.

\section{Future work}

\begin{conjecture}[Complete classification at $m\le4$]
For every $a\in\Z_{>0}^m$ with $m\le4$, the $h^*$-polynomial of $Q_{G(a)}$ is
$\gamma$-positive; for $m\ge5$ there exist $a$ for which it is not. Failure is detected
by a single sign condition on the second $\gamma$-coefficient, so the classification
reduces to bounding that window across the parallel-join, which stabilizes at four paths.
\end{conjecture}

\begin{conjecture}[Real-rootedness dichotomy]
The $h^*$-polynomial of $Q_{G(a)}$ is real-rooted iff it is $\gamma$-positive with
$\gamma$-vector supported on an interval; in the $m\le4$ regime it is nonnegative on
$[0,\infty)$ and has no positive real root.
\end{conjecture}

\begin{conjecture}[Multiplicativity as sole source at large $m$]
For $m\ge5$, the $h^*$-polynomial of $Q_{G(a)}$ is $\gamma$-positive iff it factors as a
product of $\gamma$-positive polynomials of strictly smaller order.
\end{conjecture}

\begin{conjecture}[Quantitative depth]
For the flat-type $h^*$-profiles at $m\ge5$, the most negative forced $\gamma$-coefficient
grows linearly in the total path length, so no bounded perturbation restores
$\gamma$-positivity.
\end{conjecture}

\section{Conclusion}
The $\gamma$-positive polynomials form a graded convex cone, closed under nonnegative
scaling, addition, and order-additive multiplication, and every member is nonnegative on
$[0,\infty)$. The flat palindrome is the sharp universal obstruction, $\gamma$-positive
exactly when $n\le1$, with failure forced by its two lowest coefficients; the product
model is $\gamma$-positive for every number of paths, exhibiting the multiplicative regime
that is conjectured to contain the entire $m\le4$ case. The mechanisms of failure and
success are now explicit, reducing the classification to control of a finite low-order
window across the parallel-join.

