from math import comb
from typing import List


def gamma_basis(n: int, i: int) -> List[float]:
    """B_{n,i}(t) = (1 + t)^(n - 2 i) * t^i as a low-degree-first coeff list."""
    base = [float(comb(n - 2 * i, k)) for k in range(n - 2 * i + 1)]
    return [0.0] * i + base


def gamma_vector(p: List[float], n: int) -> List[float]:
    """
    Extract the unique gamma-vector of a palindromic polynomial p of order n.

    B_{n,i} is the lowest-order basis element still reaching [t^i], so gamma_i
    is forced to the current coefficient at index i once gamma_0,...,gamma_{i-1}
    have been peeled off. Runs in O(n^2) coefficient operations.
    """
    r = list(p) + [0.0] * (n + 1 - len(p))
    gammas: List[float] = []
    for i in range(n // 2 + 1):
        gi = r[i]
        gammas.append(gi)
        b = gamma_basis(n, i)
        for k in range(len(b)):
            r[k] -= gi * b[k]
    return gammas


def is_gamma_positive(p: List[float], n: int, tol: float = 1e-9) -> bool:
    """A palindromic polynomial is gamma-positive iff every gamma_i >= 0."""
    return all(g >= -tol for g in gamma_vector(p, n))


if __name__ == "__main__":
    for n in range(6):
        F = [1.0] * (n + 1)  # flat palindrome
        print(n, gamma_vector(F, n), is_gamma_positive(F, n))

